// --- Local Testing Fallback Helpers ---
const inMemoryCache = new Map<string, any>();
const LOCAL_FILE = "local_kv.json";

const readLocalFile = (): Record<string, any> => {
  try {
    const content = Deno.readTextFileSync(LOCAL_FILE);
    return JSON.parse(content);
  } catch (_e) {
    return {};
  }
};

const writeLocalFile = (data: Record<string, any>) => {
  try {
    Deno.writeTextFileSync(LOCAL_FILE, JSON.stringify(data, null, 2));
  } catch (_e) {
    // Silently ignore permission errors (fall back to in-memory only)
  }
};

const setFallback = (key: string, value: any) => {
  inMemoryCache.set(key, value);
  const data = readLocalFile();
  data[key] = value;
  writeLocalFile(data);
};

const getFallback = (key: string): any => {
  if (inMemoryCache.has(key)) {
    return inMemoryCache.get(key);
  }
  const data = readLocalFile();
  if (key in data) {
    inMemoryCache.set(key, data[key]);
    return data[key];
  }
  return undefined;
};

const deleteFallback = (key: string) => {
  inMemoryCache.delete(key);
  const data = readLocalFile();
  delete data[key];
  writeLocalFile(data);
};
